function salary(r){const v=r.salary||{};if(v.min!=null&&v.max!=null)return v.min+'–'+v.max+' '+(v.currency==='CNY'||v.currency==='RMB'?'元':v.currency||'元')+' / '+(v.unit==='day'?'天':v.unit||'天');if(v.text)return v.text;return '薪资未披露'}
function renderRoles(){const rows=allRoles().filter(r=>(roleFilter==='all'||r.roleFamily===roleFilter)&&(salaryFilter==='all'||r.salary?.evidenceClass===salaryFilter)),active=role();
setHTML('careerRoles','<section class="roles-intro"><div><span class="eyebrow">薪资目标，不是承诺</span><h2>400–600 <small>元 / 天</small></h2><p>用真实岗位样本反推准备重点。实际薪资、名额与到岗要求，投递前逐项确认。</p></div><div class="source-freshness"><span class="tiny-label">资料最近核查</span><strong>'+date(jobs.verifiedAt||jobs.checkedAt)+'</strong><p>每周一早上核验更新，无变化不改版。核查日期来自实际读取来源。</p></div></section><p class="current-match-note"><strong>'+(jobs.summaryCounts?.confirmedCurrentEligibleTargetSalaryMatches||0)+' 条已确认当前达标岗位</strong> · 须同时核实「仍开放、本人符合资格、400–600 元/天」。本次有 '+allRoles().filter(r=>r.salary?.evidenceClass==='exact_target'&&r.status?.value==='closed').length+' 条目标区间历史薪资样本，不能视为当前岗位。</p><div class="section-heading"><div><span class="tiny-label">CHOOSE YOUR FOCUS</span><h2>一个主方向，再做有边界的拓展</h2></div></div><div class="role-directions">'+roleDefs.map(r=>'<button '+(activeRoleIds.includes(r.id)?'data-role="'+r.id+'"':'disabled')+' class="role-direction '+(active.id===r.id?'selected':'')+'" aria-pressed="'+(active.id===r.id)+'"><span>'+esc(r.tag)+'</span><h3>'+esc(r.name)+'</h3><p>'+esc(r.description)+'</p><small>'+(!activeRoleIds.includes(r.id)?'仅供了解 · 尚未配置完整路线':active.id===r.id?'当前目标 ✓':'设为当前目标 →')+'</small></button>').join('')+'</div><div class="section-heading opportunity-heading"><div><span class="tiny-label">EVIDENCE, NOT HYPE</span><h2>岗位证据库 <small>'+rows.length+' 条</small></h2></div><label class="role-select-label">方向筛选<select id="jobRoleFilter"><option value="all">全部样本</option>'+roleDefs.map(r=>'<option value="'+r.id+'" '+(roleFilter===r.id?'selected':'')+'>'+r.name+'</option>').join('')+'</select></label></div><div class="salary-filters" role="group" aria-label="薪资证据筛选">'+[['exact_target','400–600 历史样本'],['undisclosed','薪资未披露'],['overlap_only','区间部分重叠'],['below_target','低于目标'],['all','全部证据']].map(([id,label])=>'<button data-salary-filter="'+id+'" aria-pressed="'+(salaryFilter===id)+'">'+label+'</button>').join('')+'</div><div class="opportunity-list">'+rows.map((r,i)=>{const st=r.status||{},v=typeof st==='string'?st:st.value,closed=v==='closed',sc=r.salary?.evidenceClass;return '<details class="opportunity" '+(expandedRole===r.id?'open':'')+' data-opportunity="'+esc(r.id)+'"><summary><span class="company-monogram">'+esc((r.company||'岗位').slice(0,1))+'</span><div class="opportunity-main"><span class="company-name">'+esc(r.company||'岗位样本')+' · '+esc(text(r.location)||'地点见来源')+'</span><h3>'+esc(r.title)+'</h3><div class="job-tags">'+chip(closed?'已截止 · 历史样本':st.label||'开放状态未确认',closed?'muted':'amber')+chip(r.internshipType||'实习类型见来源')+'</div></div><div class="salary-cell"><strong>'+esc(salary(r))+'</strong><span>'+esc({exact_target:'样本薪资在目标范围',overlap_only:'区间仅部分重叠',undisclosed:'没有薪资证据',below_target:'低于当前目标',conflicting:'来源薪资存在冲突'}[sc]||'以来源披露为准')+'</span></div><span class="expand-symbol">＋</span></summary><div class="opportunity-detail"><p class="evidence-warning">'+esc(st.caveat||r.companyFinding||'页面可访问不等于仍在招聘。请在投递时重新核验。')+'</p><div class="job-detail-grid"><div><h4>任职与到岗要求</h4><p>'+esc(text(r.eligibility)||'以原始招聘说明为准')+'</p><p>'+esc(text(r.attendance)||'出勤要求未确认')+'</p></div><div><h4>重点能力</h4><p>'+esc(text(r.skillsRequired)||'见招聘原文')+'</p>'+(r.skillsPreferred?'<p>加分：'+esc(text(r.skillsPreferred))+'</p>':'')+'</div></div><p class="fit-note">'+esc(text(r.fit))+'</p>'+jobSkillMarkup(r)+'<ul class="source-links">'+sourceList(r.sources)+'</ul><small>来源日期：'+esc(st.sourceDate||'未披露')+' · 申请截止：'+esc(r.expiresAt||st.expiresAt||'未知，或见来源')+'</small></div></details>'}).join('')+'</div><details class="company-coverage"><summary>全部 10 家公司核查结论</summary>'+jobs.companies.map(c=>'<article><strong>'+esc(c.company)+'</strong><p>'+esc(c.overallFinding)+'</p>'+link(c.officialCareersUrl,'官方招聘入口')+(c.sources?.length?'<ul class="source-links">'+sourceList(c.sources)+'</ul>':'')+'</article>').join('')+'</details><div class="evidence-policy"><h3>怎么理解这份清单？</h3><p>'+esc(jobs.disclaimer||'历史招聘证明这种能力组合曾被招聘，不证明未来仍开放或能拿到同等薪资。薪资区间重叠也不保证你能获得上限。')+'</p><p>对 2027 年的投递，先沿主线积累能力与作品，临近投递再核对毕业时间、实习时长和实际名额。</p></div>');}
function jobSkillMarkup(r){const m=r.skillMapping;if(!m)return '<p class="job-gap">此岗位尚未逐项映射学习路线，需按原始 JD 核对。</p>';const direct=(m.directRequiredSkillIds||[]).map(id=>skills.find(s=>s.id===id)).filter(Boolean),support=(m.supportingSkillIds||[]).map(id=>skills.find(s=>s.id===id)).filter(Boolean);const buttons=list=>list.map(s=>'<button data-assess="'+s.id+'">'+esc(s.title)+' <span>'+esc(levelLabels[record(s).level||'untested'])+' · 验收 / 资料 →</span></button>').join('');return '<div class="job-skill-links"><h4>这份岗位对应的技能与进度</h4><p>'+(direct.length?'已映射技能自评 '+direct.filter(passed).length+' / '+direct.length+' · 仅表示这些技能的自评证据，不表示全部 JD 已满足。':'核心要求尚未被本路线直接覆盖，不能据此判断已准备充分。')+'</p><div>'+direct.map(sk=>'<div class="job-skill-target">'+buttons([sk])+'<p>'+esc(m.directCoverageNotes?.[sk.id]||'仅覆盖本技能量表范围。')+'</p></div>').join('')+'</div>'+(support.length?'<details class="job-support"><summary>辅助准备能力 ('+support.length+')</summary><div>'+buttons(support)+'</div></details>':'')+'<p class="job-gap"><strong>尚未覆盖 / 需要单独确认：</strong>'+esc(text(m.uncoveredRequirements)||'仍需核对实际业务、出勤与资格要求。')+'</p>'+(m.nonSkillBlockers?.length?'<p class="job-gap"><strong>资格、出勤与薪资：</strong>'+esc(text(m.nonSkillBlockers))+'</p>':'')+(m.mappingNote?'<p>'+esc(m.mappingNote)+'</p>':'')+'</div>'}
function renderSkills(){const current=relevant(),other=skills.filter(s=>!current.some(c=>c.id===s.id));
setHTML('careerSkills','<div class="map-toolbar"><div><h2>你的目标能力地图</h2><p>'+esc(role().description)+'</p></div>'+roleSelect()+'</div><div class="level-legend">'+Object.entries(levelLabels).map(([k,v])=>'<span><i class="level-dot '+k+'"></i>'+v+'</span>').join('')+'</div><div class="skill-table"><div class="skill-table-head"><span>能力与证据标准</span><span>当前状态</span><span>学习 / 验收</span></div>'+current.map((s,i)=>skillRow(s,i)).join('')+'</div>'+(other.length?'<details class="other-skills"><summary>其他方向能力与选修 ('+other.length+')</summary><div class="skill-table">'+other.map((s,i)=>skillRow(s,i)).join('')+'</div></details>':'')+'<p class="quiet-note">“实操通过”仅代表按当前量表自行验收，并保存了证据。本站没有第三方审核，不把学完课程自动记为技能掌握。</p>');}
function skillRow(s,i){const r=record(s),study=skillStudy(s),pre=(s.prerequisites||[]).map(id=>skills.find(x=>x.id===id)?.title).filter(Boolean);return '<article class="skill-table-row"><div class="skill-name"><span>'+String(i+1).padStart(2,'0')+'</span><div><h3>'+esc(s.title)+'</h3><p>'+esc(s.assessment?.title||s.description||'用实操交付验证能力')+'</p>'+(pre.length?'<small>前置：'+esc(pre.join('、'))+'</small>':'')+'</div></div><div class="skill-status">'+chip(levelLabels[r.level||'untested'],r.level==='passed'?'green':'')+(r.assessedAt?'<small>'+date(r.assessedAt)+' · 量表 '+(r.score||0)+'%</small>':'<small>尚未留下验收记录</small>')+'<small>学习 '+study.done+' / '+study.total+' 单元</small></div><div class="skill-actions"><button data-assess="'+s.id+'">'+(r.assessedAt?'查看 / 再次验收':'查看实操验收')+' →</button><button class="muted-link" data-learn-skill="'+s.id+'">对应学习资料</button></div></article>'}
function unitReference(u){const reference=role().id==='agent_engineering'?projectOutline().growthLevels?.[0]?.steps?.flatMap(x=>x.resources||[]).find(x=>x.unitId===u.id):null;return {title:reference?.title||u.title,url:reference?.url||u.url,scope:reference?.scope||u.readingGuide||u.scope};}
function moduleLessonMarkup(u,index,first){const done=unitDone(u),copy=flowData().unitLabels?.[u.id]||{},pid=u.canonicalProgressId||u.id,agent=role().id==='agent_engineering',reference=unitReference(u),opened=openUnitIds.has(u.id)||first===u.id&&!closedUnitIds.has(u.id);return '<details class="module-lesson '+(done?'is-done':'')+'" data-module-unit="'+esc(u.id)+'" '+(opened?'open':'')+'><summary><span class="lesson-order">'+(done?'✓':String(index+1).padStart(2,'0'))+'</span><span class="module-lesson-name"><strong>'+esc(unitTitle(u))+'</strong><small>'+(first===u.id&&!done?'下一节 · ':'')+'约 '+duration(u.estimatedMinutes||60)+'</small></span><span class="module-lesson-state">'+(done?'原练习已完成':'未完成')+'</span><span class="module-expand" aria-hidden="true">＋</span></summary><div class="module-lesson-body"><div class="lesson-instructions"><h4>看什么</h4><p>'+esc(reference.scope)+'</p>'+link(reference.url,'打开课程：'+reference.title,'outline-button')+'</div>'+(agent&&copy.projectApply?'<aside class="lesson-purpose"><strong>用于当前任务</strong><p>'+esc(copy.projectApply)+'</p></aside>':'')+'<details class="original-course-practice"><summary>原课程练习（保留记录）</summary><div class="lesson-instructions"><h4>原资料范围</h4><p>'+esc(u.readingGuide||u.scope)+'</p><h4>练习题</h4><p>'+esc(copy.exercise||u.exercise||'照着资料做一次，并用自己的输入再运行一次。')+'</p><h4>原练习完成标准</h4><p>'+esc(copy.done||'做完上面的练习，能解释自己改了什么，再勾选。')+'</p></div><label class="module-complete-check"><input id="unit-check-'+esc(pid)+'" type="checkbox" data-unit-check="'+esc(pid)+'" '+(done?'checked':'')+'>原课程练习做完了</label><p class="module-reference-note">课程与当前任务分别记进度。</p></details><details class="module-source-detail"><summary>资料说明 / 相关旧课</summary><p>'+esc(u.provider||'官方资料')+' · '+esc(u.language||'语言见资料')+'</p><p>'+esc(u.skipScope||'只看本节范围。')+'</p>'+((u.relatedLessonIds||[]).map(id=>{const l=(root.COURSE_LESSONS?.courses||[]).flatMap(c=>c.lessons).find(l=>l.id===id);return l?'<button data-open-lesson="'+esc(id)+'">'+esc(l.title)+' →</button>':''}).join('')||'<p>这节没有对应的旧课。</p>')+'</details></div></details>'}
function firstSessionMarkup(m){if(!isFirstSession(m)||milRecord(mainProject(),mainProject().milestones.find(x=>(x.moduleIds||[x.moduleId]).includes(m.id))||{}).status==='done')return '';const f=firstSession();return '<details class="first-session-guide"><summary>第一次运行：下载样例与操作步骤</summary><section class="first-session" id="firstSession" aria-labelledby="firstSessionTitle"><div class="session-heading"><span class="home-overline">作品起步 · 约 '+esc(f.minutes)+' 分钟</span><span class="session-boundary">先做一个小结果</span></div><h2 id="firstSessionTitle">'+esc(f.title)+'</h2><p class="session-output">'+esc(f.output)+'</p><p class="session-download"><a class="outline-button" href="./data/work-agent-starter.zip" download>下载8条虚构练习资料 ↓</a><small>仅输入资料和核对答案，不是完成的Agent。</small></p><div class="session-sample"><span>'+esc(f.sampleLabel)+'</span><div>'+f.sample.slice(0,3).map(x=>'<p><strong>'+esc(x.id)+'</strong><span>'+esc(x.version)+'</span><span>'+esc(x.text)+'</span></p>').join('')+'</div></div><ol class="session-steps">'+(f.steps||[]).map((step,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span><div><h3>'+esc(step.title)+'<small>'+esc(step.minutes)+'</small></h3><p>'+esc(role().id==='agent_engineering'?step.text.replaceAll('feedback_check.py','analyze.py'):step.text)+'</p></div></li>').join('')+'</ol><details class="session-prompt"><summary>需要 AI 起草时，用这段要求</summary><p>'+esc(f.codingPrompt)+'</p><small>让 AI 起草之后，仍要亲自运行、改输入和核对结果。</small></details><div class="session-expected"><strong>用这三种情况核对</strong><ul>'+f.expected.map(x=>'<li><span>'+esc(x.label)+'</span><strong>'+esc(x.result)+'</strong><small>'+esc(x.reason)+'</small></li>').join('')+'</ul></div><details class="session-materials"><summary>环境没准备好或卡住时，看这里</summary>'+f.materials.map(x=>'<p>'+link(x.url,x.title)+'<span>'+esc(x.scope||'')+'</span></p>').join('')+'<p class="session-environment">'+esc(f.environmentNote)+'</p></details><div class="session-save"><strong>结束时，文件放哪里？</strong><p>'+esc('代码与结果留在电脑；回任务列表保存进度。')+'</p><p>'+esc('下次继续同一任务，不需要另建项目。')+'</p></div><p class="session-completion-note">'+esc(f.completionNote.replace('下方完整90分钟原诊断','完整90分钟原诊断'))+'</p><div class="session-next"><span>'+esc(f.dataNote)+'</span><button class="text-action" data-session-next>需要时查原课练习 ↓</button></div></section></details>'}
function renderLegacyLearning(archived=false){const m=currentModule();if(!m){setHTML('careerLearning','<p>学习内容暂时无法载入，请刷新页面。</p>');return}selectedModule=m.id;const ms=modules(),index=ms.findIndex(x=>x.id===m.id),st=moduleStats(m),us=moduleUnits(m),first=(us.find(u=>!unitDone(u))||us[0])?.id,previous=ms[index-1],next=ms[index+1],checks=(m.skillIds||[]).map(id=>skills.find(s=>s.id===id)).filter(Boolean),agent=role().id==='agent_engineering',stage=agent?mainProject().milestones.find(x=>(x.moduleIds||[x.moduleId]).includes(m.id)):null;
setHTML('careerLearning',(!archived?courseLinksMarkup(m):'')+courseDirectoryMarkup(m)+'<div class="module-breadcrumb">'+button('execution','← 返回任务列表')+'<span>'+(m.optional?'选修 · 按需补充':'课程模块 '+(index+1)+' / '+ms.length)+'</span></div>'+'<section class="module-intro"><div><span class="flow-small-label">'+(agent?'基础补强 · 按需':m.optional?'按需补充':st.done===st.total?'已学完 · 回看':'下一节')+'</span><h2 class="sr-only">'+esc(m.title)+'</h2><p>'+esc(us.find(u=>u.id===first)?unitTitle(us.find(u=>u.id===first)):m.title)+'</p></div><span class="module-total"><strong>'+st.done+' <small>/ '+st.total+'</small></strong>节已完成</span><div class="module-make">'+(us.find(u=>u.id===first)?link(unitReference(us.find(u=>u.id===first)).url,agent?'打开基础参考':'打开本节课程','outline-button'): '')+'<button class="outline-button" data-open-course-unit="'+esc(first||'')+'">'+(st.done===st.total?'回看课节':'查看本节练习')+' ↓</button></div></section>'+(agent?moduleProjectMarkup(m):'')+(st.selfPassed&&st.done<st.total?'<p class="module-self-passed-note">已有对应的旧练习自查记录；未勾选的小节仍保留。'+(agent?'它不会完成当前作品阶段。':'自查通过不代表这些小节已完成。')+'</p>':'')+(!agent&&index===0?'<aside class="module-try"><div><strong>这些已经会了？</strong><p>可以先试一个小题。不会的地方，再回来学。</p></div>'+(checks[0]?'<button data-assess="'+esc(checks[0].id)+'" class="outline-button">先试试 →</button>':'')+'</aside>':'')+'<section class="module-lessons" aria-label="本模块的具体小节"><div class="module-section-heading"><h3>'+(agent?'基础课节与原练习':'课程小节')+'</h3><span>点标题展开</span></div>'+(agent?'<p class="module-reference-note">资料按需阅读；原练习放在每节的折叠项内。</p>':'')+us.map((u,i)=>moduleLessonMarkup(u,i,first)).join('')+'</section><details class="module-finish"><summary>原练习自查</summary><span class="flow-small-label">'+(agent?'补充检查 · 旧练习记录':'怎么知道这一步做完了')+'</span><h3>'+esc(agent?'需要时，用旧练习检查基础能力':m.done||'完成上面的练习，留下能重新运行的代码和结果。')+'</h3><p>'+(agent?'这些自查保留原题面和记录，只作参考，不是当前作品的必过门槛。作品按本页上方的交付和验收标准记录。':'课节勾选只记录练习完成。想检查是否真的会做，可以展开下面的自查。')+'</p><details class="module-self-check"'+detailAttrs('self-'+m.id)+'><summary>'+(agent?'查看旧练习自查 / 保存记录':'检查自己会不会 / 保存结果')+(checks.some(passed)?'（已有自评记录）':'')+'</summary><div>'+checks.map(s=>'<div class="module-check-row"><div><strong>'+esc(s.title)+'</strong><span>'+esc(levelLabels[record(s).level||'untested'])+'</span></div><button data-assess="'+esc(s.id)+'">'+(passed(s)?'查看记录':'去做自查')+' →</button></div>').join('')+'<p>详细标准和结果记录在自查页。由你自己检查，不是外部认证，也不会自动勾选课程或完成作品。</p></div></details>'+(!agent?moduleProjectMarkup(m):'')+'</details>'+firstSessionMarkup(m)+growthLadderMarkup('learning')+(m.branches?.length?'<details class="module-optional"'+detailAttrs('optional-'+m.id)+'><summary>可选内容：需要时再学（'+m.branches.length+' 组）</summary><div>'+m.branches.map(b=>'<article><div><h3>'+esc(b.title)+'</h3><p>'+esc(b.description||'选修，不影响上面的学习顺序。')+'</p><small>'+moduleStats(b).done+' / '+moduleStats(b).total+' 节已完成</small></div>'+moduleButton(b,'看看选修 →')+'</article>').join('')+'</div></details>':'')+'<div class="module-navigation">'+(m.optional?moduleButton(allModules().find(x=>x.id===m.parentId),'← 返回主线模块','outline-button'):previous?moduleButton(previous,'← 上一组课程：'+previous.title,'outline-button'):button('execution','← 返回任务列表','outline-button'))+(next?moduleButton(next,'下一组课程：'+next.title+' →','outline-button'):!m.optional?button('today','查看发展路线 →','outline-button'):'')+'</div>');}
