function videoReleaseLabel(resource){return (resource.publicationScope==='course'?'课程发布 ':'发布 ')+(resource.publishedAt||'日期待核验')}
function videoCardMarkup(resource,index){
  const mapped=resource.skillIds.map(id=>skills.find(skill=>skill.id===id)).filter(Boolean);
  return '<article class="video-course-card" data-video-resource="'+esc(resource.id)+'"><header><span class="video-order">'+String(index+1).padStart(2,'0')+'</span><div><span class="video-provider">'+esc(resource.author||resource.provider)+' · '+esc(resource.language)+(resource.durationLabel?' · '+esc(resource.durationLabel):'')+'</span><h3>'+esc(resource.title)+'</h3><p class="video-episode">'+esc(resource.episodeLabel)+'</p></div></header><p class="video-release-meta"><span>'+esc(videoReleaseLabel(resource))+'</span><span>'+esc(resource.technologySummary||'版本未标注')+'</span></p><p class="video-watch-scope">'+esc(resource.watchScope)+'</p><div class="video-skill"><span>学会什么</span><strong>'+esc(resource.skillLabel)+'</strong></div><dl class="video-application"><div><dt>做到项目里</dt><dd>'+esc(resource.practice)+'</dd></div><div><dt>小验收</dt><dd>'+esc(resource.check)+'</dd></div></dl><footer class="video-card-actions">'+link(resource.url,'看这节视频','primary-button')+taskLink(resource.taskId,'对应任务 →')+'</footer><details class="video-skill-detail"><summary>对应能力与实操自查</summary><p>这节视频只覆盖下列能力的一部分。完成项目后，再按完整标准自查。</p><div>'+mapped.map(skill=>'<button class="text-action" data-assess="'+esc(skill.id)+'">'+esc(skill.title)+' →</button>').join('')+'</div></details><details class="video-source-note"><summary>来源与观看说明</summary><p>'+esc(resource.accessNote||videoData().playbackNote||'完整观看可能需登录。')+'</p><p>'+esc(resource.versionNote||'按自己的项目环境练习。')+'</p><small>'+esc(resource.sourceVerification||'')+'</small></details></article>';
}
// Read the existing watch/practice IDs only; viewing a link never completes a lesson.
function courseState(resource){const values=lessonValues();return {watch:values['watch-'+resource.id]==='done',practice:values['practice-'+resource.id]==='done'}}
function courseRecordButton(resource,kind,label){return '<button class="text-action" data-course-record="'+esc(kind+'-'+resource.id)+'">'+esc(label)+' →</button>'}
function courseOverviewMarkup(){
 const resources=videoData().resources||[],watched=resources.filter(r=>courseState(r).watch).length,practiced=resources.filter(r=>courseState(r).practice).length;
 const next=resources.find(r=>!courseState(r).watch||!courseState(r).practice),nextVideo=resources.find(r=>!courseState(r).watch),state=next&&courseState(next),stage=videoData().stages.find(s=>s.taskId===next?.taskId);
 const head='<header class="course-overview-heading"><div><span class="flow-small-label">课程学习 · 反馈分析 Agent</span><h2>看一节，做一小步</h2></div><p class="course-real-progress">观看 <strong>'+watched+' / '+resources.length+'</strong> · 练习 <strong>'+practiced+' / '+resources.length+'</strong><small>'+(watched===0&&practiced===0?'尚无完成记录':'按实际勾选记录')+' · 与项目交付分别计算</small></p></header>';
 const focus=next?'<section class="course-next" aria-labelledby="courseNextTitle"><div class="course-next-heading"><span class="flow-small-label">现在'+(state.watch?'做练习':'看这节')+' · '+esc(stage?.title||'')+'</span><h3 id="courseNextTitle">'+esc(next.title)+'</h3><p>'+esc(next.episodeLabel)+' · '+esc(next.durationLabel)+' · '+esc(next.author)+'</p></div><div class="course-next-actions">'+link(next.url,state.watch?'回看这节视频':'开始看这节视频','primary-button')+courseRecordButton(next,state.watch?'practice':'watch',state.watch?'练习验收与记录':'看完后记录')+'</div><dl class="course-next-check"><div><dt>学完做什么</dt><dd>'+esc(next.practice)+'</dd></div><div><dt>核对结果</dt><dd>'+esc(next.check)+'</dd></div></dl><p class="course-next-skill">对应能力：'+esc(next.skillLabel)+'</p>'+(state.watch&&nextVideo?'<p class="course-next-video">下一节未看：'+link(nextVideo.url,nextVideo.shortTitle||nextVideo.title)+'</p>':'')+'</section>':'<section class="course-next"><h3>7 节观看与对应练习均已记录完成</h3><p>继续核对作品交付；课程完成不代表作品验收通过。</p>'+taskLink(mainProject().milestones.find(m=>milRecord(mainProject(),m).status!=='done')?.id||mainProject().milestones[0].id,'查看项目交付')+'</section>';
 const catalog='<section class="course-catalog" aria-labelledby="courseCatalogTitle"><div class="course-catalog-heading"><h3 id="courseCatalogTitle">全部 '+resources.length+' 节 · 按原学习顺序</h3><span>直接看课，或展开任务详解</span></div>'+videoData().stages.map((group,i)=>'<details class="course-group" open><summary><strong>'+String(i+1).padStart(2,'0')+' '+esc(group.title)+'</strong><span>'+taskVideos(group.taskId).filter(r=>courseState(r).watch).length+' / '+taskVideos(group.taskId).length+' 节已看</span></summary><div>'+taskVideos(group.taskId).map(r=>{const st=courseState(r);return '<article class="course-compact-row" data-course-overview="'+esc(r.id)+'"><div class="course-compact-title"><strong>'+esc(r.shortTitle||r.title)+'</strong><small>'+esc(r.episodeLabel)+' · '+esc(r.durationLabel)+'</small><span>'+esc(r.skillLabel)+'</span></div><div class="course-compact-status"><span>'+(st.watch?'已看完':'未看完')+' · '+(st.practice?'练习已完成':'练习未完成')+'</span>'+link(r.url,'看视频','text-action')+courseRecordButton(r,st.watch?'practice':'watch',st.watch?'练习记录':'观看记录')+'</div></article>'}).join('')+'<button class="text-action course-group-detail" data-open-module="'+esc(group.moduleIds[0])+'">查看这一组的练习与验收 ↓</button></div></details>').join('')+'</section>';
 return head+focus+catalog;
}
function renderLearning(){
  if(role().id!=='agent_engineering'){renderLegacyLearning();return}
  const m=currentModule(),stage=videoStage(m);
  if(!m||!stage){renderLegacyLearning(true);const original=document.getElementById('careerLearning')?.innerHTML||'';setHTML('careerLearning','<p>视频课程暂时无法载入，请刷新页面。以前的练习与记录仍可在下方查看。</p><details class="video-practice-archive"><summary>以前的基础练习与记录</summary>'+original+'</details>');return}
  renderLegacyLearning(true);
  const legacy=document.getElementById('careerLearning')?.innerHTML||'',p=mainProject(),current=p.milestones.find(item=>milRecord(p,item).status!=='done'),index=p.milestones.findIndex(item=>item.id===stage.taskId),resources=taskVideos(stage.taskId),done=milRecord(p,{id:stage.taskId}).status==='done';
  const direction='<section class="video-direction" aria-labelledby="videoDirectionTitle"><span class="flow-small-label">AI Agent 应用研发</span><h2 id="videoDirectionTitle">先做出一个能用的 Agent</h2><ol class="video-direction-steps" aria-label="学习方向"><li class="is-current"><strong>Agent 应用</strong><span>现在学</span></li><li><strong>检索与评测</strong><span>作品跑通后</span></li><li><strong>后训练</strong><span>再补训练基础</span></li></ol><p>'+esc(videoData().editionLabel||'按当前任务选视频')+'。视频学方法，项目练技能。</p></section>';
  const navigation='<nav class="video-task-tabs" aria-label="按项目任务选择视频">'+videoData().stages.map((item,i)=>'<button class="'+(item.taskId===stage.taskId?'is-selected':'')+'" data-open-module="'+esc(item.moduleIds[0])+'" '+(item.taskId===stage.taskId?'aria-current="page"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(item.title)+'</button>').join('')+'</nav>';
  const intro='<section class="video-current-task"><div><span class="video-task-kicker">任务 '+(index+1)+(done?' · 作品已自查完成':current?.id===stage.taskId?' · 现在做':' · 后续任务')+'</span><h2>'+esc(stage.goal)+'</h2><p>'+resources.length+' 节视频，按下面顺序看。每看完一节，就改一次自己的项目。</p></div>'+taskLink(stage.taskId,'打开任务与保存进度 →')+'</section>';
  const videoArchive=(videoData().archivedResources||[]).length?'<details class="video-resource-archive"'+detailAttrs('video-resource-archive')+'><summary>以前推荐的视频</summary><p>'+esc(videoData().archiveNote||'保留旧链接，资源身份和已有学习记录不互相替换。')+'</p><ul>'+(videoData().archivedResources||[]).map(resource=>'<li data-archived-video-resource="'+esc(resource.id)+'">'+link(resource.url,resource.episodeLabel+' · '+resource.author)+'</li>').join('')+'</ul></details>':'';
  const archive='<details class="video-practice-archive"'+detailAttrs('video-practice-archive')+'><summary>以前的基础练习与记录</summary><p>以下是原来的参考课节、练习题与自查，记录仍按原标准保存，不算作新视频的完成。需要时再回看。</p>'+legacy+'</details>';
  setHTML('careerLearning','<div class="video-learning">'+courseOverviewMarkup()+'<h2 class="course-detail-title" tabindex="-1">任务详解</h2>'+navigation+intro+'<section class="video-course-list" aria-label="当前任务的视频清单">'+resources.map(videoCardMarkup).join('')+'</section><p class="video-progress-note">每节观看和对应练习都在任务清单里独立打卡。项目交付与原课程、自查记录分别保存。</p><details class="course-direction-detail"><summary>学习方向与后续路线</summary>'+direction+'</details></div>'+videoArchive+archive);
}
function challengeMarkup(s){const cs=(curriculum.challenges||[]).filter(c=>(s.assessment?.challengeIds||[]).includes(c.id)||(c.skillIds||[]).includes(s.id));return cs.map(c=>'<details class="challenge"><summary>练习题：'+esc(c.title)+'</summary><p>'+esc(c.task)+'</p><div class="challenge-inputs">输入文件：'+esc((c.inputFiles||[]).join('、'))+'</div><a class="outline-button" href="./data/career-challenge-starters.zip" download>下载题目数据与说明 ↓</a><details><summary>展开已知样例的核对结果</summary><pre>'+esc(JSON.stringify(c.expected,null,2))+'</pre></details><p>故障边界：'+esc(text(c.failureCases))+'</p><p>变式答辩练习（公开）：'+esc(c.defenseTask||c.unseenDefense)+'</p><small>样例结果用于核对，不是你已完成的证据。仍需自行运行、补测试与处理变式。</small></details>').join('')}
function renderAssessments(){const s=skills.find(x=>x.id===selectedAssessment)||nextSkill()||skills[0];if(!s){setHTML('careerAssessments','<p>能力资料正在准备。</p>');return}selectedAssessment=s.id;const r=record(s),a=s.assessment||{},criteria=a.criteria||[];
setHTML('careerAssessments','<div class="assessment-layout focused-assessment"><details class="assessment-queue assessment-queue-collapsed"><summary>其他自查项目</summary><div>'+skills.map(sk=>'<button data-assessment-choice="'+sk.id+'" class="'+(sk.id===s.id?'selected':'')+'"><span class="level-dot '+(record(sk).level||'untested')+'"></span><span>'+esc(sk.title)+'</span>'+(passed(sk)?'<small>通过</small>':'')+'</button>').join('')+'</div></details><section class="assessment-workbench"><div class="assessment-header"><span class="eyebrow">'+esc(s.id).toUpperCase()+'</span>'+chip(levelLabels[r.level||'untested'],r.level==='passed'?'green':'')+'</div><h2>'+esc(a.title||s.title)+'</h2><div class="assessment-learning-link"><button data-learn-skill="'+s.id+'">← 回到对应学习模块</button></div><div class="assessment-meta"><span>建议 '+duration(a.minutes||60)+'</span><span>方式：实操 + 证据自评</span><span>逐项完成后，再保存自查</span></div><div class="assessment-brief"><h3>你要完成什么</h3><p>'+esc(a.task||a.description||s.description||a.title)+'</p><p class="ai-policy">AI 使用：'+esc(text(a.allowedAI)||'可以辅助；必须能独立解释、修改和验证结果。')+'</p>'+(a.transferTask?'<p><strong>迁移检查：</strong>'+esc(text(a.transferTask))+'</p>':'')+'</div>'+challengeMarkup(s)+'<form id="assessmentForm" data-skill-id="'+s.id+'"><fieldset class="rubric"><legend>对照下面几项，检查结果</legend><p>只有真的完成且留有证据，才勾选对应标准。</p>'+criteria.map((c,i)=>'<label><input type="checkbox" name="criterion" value="'+esc(c.id)+'" '+(Number(r.rubric?.[c.id])===4?'checked':'')+'><span><strong>'+String(i+1).padStart(2,'0')+'</strong>'+esc(c.text||c.title)+'</span></label>').join('')+'</fieldset><div class="evidence-form"><h3>留下可复查的证据</h3><p>'+esc(text(a.evidenceRequired)||'代码、测试结果、指标表或复盘。至少填写一个证据链接或有效说明。')+'</p><label for="evidenceUrl">仓库 / 报告 / 演示链接</label><input id="evidenceUrl" name="evidenceUrl" type="url" maxlength="2048" placeholder="https://…" value="'+esc(r.evidenceUrl||'')+'"><label for="evidenceNote">结果与复盘</label><textarea id="evidenceNote" name="evidenceNote" rows="5" maxlength="2000" placeholder="做了什么；测试与指标结果；哪里仍有不足。不要填写密码、密钥或敏感数据。">'+esc(r.evidenceNote||'')+'</textarea><small>仅保存在本机或你的私有同步账号；不要粘贴密码、API 密钥或访问令牌。链接不会自动上传或公开文件，访问权限仍由原平台决定。</small></div><p id="assessmentError" role="alert" class="form-error"></p><div class="assessment-submit"><button class="primary-button" type="submit">保存这次实操自评 →</button><span>不会修改课程完成状态</span></div></form>'+(r.assessedAt?'<div class="assessment-result"><strong>'+esc(levelLabels[r.level])+' · 量表 '+r.score+'%</strong><p>记录于 '+date(r.assessedAt)+'。这是自评证据覆盖率，不是招聘通过率。</p>'+(r.evidenceUrl?link(r.evidenceUrl,'打开已存证据'):'')+'</div>':'')+(r.history?.length?'<details class="assessment-history"><summary>此前验收记录 ('+r.history.length+')</summary>'+r.history.map(h=>'<p>'+date(h.assessedAt)+' · '+(h.score||0)+'% · '+esc(levelLabels[h.level]||'实操记录')+'</p>').join('')+'</details>':'')+'</section></div>');}
function archivedAssistantMarkup(){return (projectOutline().archivedProjects||[]).map(p=>'<details class="archived-assistant-plan"'+detailAttrs('archive-'+p.projectId)+'><summary>以前的航班比较方案与 '+p.milestones.length+' 项记录</summary><div class="archived-assistant-intro"><h3>'+esc(p.mainTitle)+'</h3><p>'+esc(p.oneLine)+'</p><p>'+esc(p.demo)+'</p><p>原状态、证据和日期按原标准保存，不算作当前 AI 工作助理完成，也不是现在必须做的主项目。</p></div>'+p.milestones.map(m=>projectStageMarkup(m,false,{id:p.projectId,milestones:p.milestones},true)).join('')+'</details>').join('')}
function renderProjects(){setHTML('careerProjects',proposedProjectMarkup()+archivedAssistantMarkup()+'<details class="legacy-project-plan"'+detailAttrs('legacy-project-plan')+'><summary>以前的项目方案与记录</summary><p class="legacy-plan-note">下面是以前的预测与资源安排练习。名称、任务和进度原样保留，不算作上方新项目的完成。</p>'+projects.map(p=>{const done=requiredMilestones(p).filter(m=>milRecord(p,m).status==='done').length;return '<section class="project-intro"><div><span class="eyebrow">FLAGSHIP PROJECT / 01</span><h2>'+esc(p.title)+'</h2><p>'+esc(text(p.scope)||p.description)+'</p><div class="project-stack"><span>'+(role().id==='agent_engineering'?'数据工具':'预测')+'</span><i>→</i><span>'+(role().id==='agent_engineering'?'Agent接口':'优化')+'</span><i>→</i><span>评测</span><i>→</i><span>可运行产品</span></div></div><div class="project-number"><strong>'+done+'<small> / '+requiredMilestones(p).length+'</small></strong><span>主线里程碑已验收</span></div></section><div class="project-principles"><div><strong>可复现</strong><span>固定环境、数据版本与随机种子</span></div><div><strong>有对照</strong><span>基线、回测、成本收益与失败案例</span></div><div><strong>能演示</strong><span>README、测试、启动命令与演示脚本</span></div></div><div class="track-summary"><strong>'+esc(track()?.title||role().name)+'</strong><p>'+esc(track()?.summary||'')+'</p><p>'+esc(track()?.note||'')+'</p><small>本路线约 '+(track()?.estimatedHours||'—')+' 小时（包含对应学习与验收，不重复加时）；最早 MVP 约 '+(track()?.mvpEstimatedHours||'—')+' 小时。</small>'+roleSelect()+'</div>'+dataPolicyMarkup(p)+'<div class="section-heading"><h2>分阶段，把 Demo 做成产品</h2><span>完成验收再标记，不按月份自动推进</span></div><div class="project-milestones">'+p.milestones.map((m,i)=>{const r=milRecord(p,m);return '<details class="project-milestone '+(r.status==='done'?'done':'')+'" '+(selectedProject===m.id||(!selectedProject&&i===done)?'open':'')+' data-project-detail="'+m.id+'"><summary><span class="milestone-index">'+(r.status==='done'?'✓':String(i).padStart(2,'0'))+'</span><div><div class="milestone-tags"><span>'+esc(m.targetMonth||'按验收推进')+' · '+(track()?.optionalMilestoneIds?.includes(m.id)?'本方向选修':'本方向必需')+'</span>'+chip({todo:'待推进',doing:'进行中',done:'已验收 · 自评'}[r.status||'todo'],r.status==='done'?'green':'')+'</div><h3>'+esc(m.title)+'</h3><p>'+esc(text(m.summary)||text(m.deliverables).slice(0,95))+'</p></div><span class="expand-symbol">＋</span></summary><div class="milestone-body">'+(track()?.milestoneNotes?.[m.id]?'<p class="evidence-warning">'+esc(track().milestoneNotes[m.id])+'</p>':'')+'<div class="milestone-detail-grid"><div><h4>交付物</h4><ul>'+toList(m.deliverables)+'</ul></div><div><h4>验收标准</h4><ul>'+toList(m.acceptance)+'</ul></div></div><div class="milestone-skills">对应能力：'+(m.skillIds||[]).map(id=>{const s=skills.find(s=>s.id===id);return s?'<button data-assess="'+id+'">'+esc(s.title)+' ↗</button>':''}).join('')+'</div><form data-milestone-form="'+m.id+'" data-project-id="'+p.id+'"><label>推进状态<select name="milestoneStatus"><option value="todo" '+(!r.status||r.status==='todo'?'selected':'')+'>待推进</option><option value="doing" '+(r.status==='doing'?'selected':'')+'>进行中</option><option value="done" '+(r.status==='done'?'selected':'')+'>已完成验收（自评）</option></select></label><label>交付证据链接<input type="url" name="milestoneEvidence" placeholder="https://…" value="'+esc(r.evidenceUrl||'')+'" maxlength="2048"></label><label class="milestone-attest"><input type="checkbox" name="milestoneAttest" '+(r.status==='done'?'checked':'')+'>我已逐项检查上方标准，并在链接中提供结果。</label><div class="form-error" role="alert"></div><button class="outline-button" type="submit">保存里程碑状态</button>'+(r.completedAt?'<small>实际完成：'+date(r.completedAt)+'</small>':'')+'</form></div></details>'}).join('')+'</div>'}).join('')+'<div class="legacy-project-link"><p>原有 AirDemandLab、EnterpriseAgentLab、VisionLab 的任务和勾选历史继续保留。主线项目在这里单独验收。</p>'+button('outcomes','查看原有成果路线 →')+'</div></details>');}
function dataPolicyMarkup(p){const d=p.dataPolicy;if(!d||typeof d==='string')return '<p class="data-policy">数据边界：'+esc(d||'仅使用公开或明确授权、经过脱敏的数据。')+'</p>';const source=d.primaryDataset||{};return '<details class="data-policy-details"><summary>数据与真实性边界 · '+esc(source.title||'公开数据 + 合成情景')+'</summary><div><p>'+link(source.url,source.title||'数据来源')+' · '+link(source.licenseUrl,source.license||'许可条款')+'</p><p>'+esc(source.contents||'')+'</p><ul>'+toList((source.limitations||[]).slice(0,4))+'</ul><p>合成情景字段：'+esc(text(d.syntheticFields))+'</p><p>'+esc(d.aviationAdapter||'')+'</p><p>不据此声称：'+esc(text(d.noClaims))+'。</p></div></details>'}
function toList(v){return(Array.isArray(v)?v:[v]).filter(Boolean).map(x=>'<li>'+esc(text(x))+'</li>').join('')}
